class Connection(object):
    """Represents a connection to Amazon S3

    Currently, this just dispatches everything to boto. Note
    that boto is not threadsafe, so we need to create a
    separate s3 connection for each thread.
    """

    def __init__(self, awskey, awspass, encrypt=None):
        self.awskey = awskey
        self.awspass = awspass
        self.encrypt = encrypt

        self.tlocal = threading.local()

        self.tlocal.boto = S3Connection(awskey, awspass)

    def delete_bucket(self, name, recursive=False):
        """Deletes a bucket from S3.

        Fails if there are objects in the bucket and `recursive` is
        `False`.
        """
        boto = self.get_boto()

        if recursive:
            bucket = boto.get_bucket(name)
            for s3key in bucket.list():
                bucket.delete_key(s3key)

        boto.delete_bucket(name)

    def get_boto(self):
        """Returns boto s3 connection local to current thread.
        """

        if not hasattr(self.tlocal, "boto"):
            self.tlocal.boto = S3Connection(self.awskey, self.awspass)

        return self.tlocal.boto


    def create_bucket(self, name):
        """Creates an S3 bucket
        """
        boto = self.get_boto()
        boto.create_bucket(name)


    def get_bucket(self, name):
        """Returns a bucket instance for the bucket `name`

        If the bucket doesn't exist, it is created first.
        """
        if not self.bucket_exists(name):
            self.create_bucket(name)

            # S3 needs some time before we can fetch the bucket
            waitfor(10, self.bucket_exists, name)

        return Bucket(self, name)

    def bucket_exists(self, name):
        """Checks if the bucket `name` exists.
        """
        boto = self.get_boto()
        try:
            boto.get_bucket(name)
        except bex.S3ResponseError, e:
            if e.status == 404:
                return False
            else:
                raise
        else:
            return True

class my_cursor(object):
    """Wraps an apsw cursor to add some convenience functions.
    """

    def __init__(self, cursor):
        self.cursor = cursor
        self.conn = cursor.getconnection()

    def execute(self, *a, **kw):
        return self.cursor.execute(*a, **kw)

    def get_val(self, *a, **kw):
        """Executes a select statement and returns first element of first row.

        If there is no result row, return None.
        """

        try:
            return self.execute(*a, **kw).next()[0]
        except StopIteration:
            return None

    def get_list(self, *a, **kw):
        """Executes a select statement and returns result list.
        """

        return list(self.execute(*a, **kw))

    def get_row(self, *a, **kw):
        """Executes a select statement and returns first row.

        If there are no result rows, returns None.
        """

        res = self.execute(*a, **kw)
        try:
            row = res.next()
        except StopIteration:
            row = None

        return row        

    def last_rowid(self):
        """Returns last inserted rowid.

        Note that this returns the last rowid that has been inserted using
        this *connection*, not cursor.
        """
        return self.conn.last_insert_rowid()

    def changes(self):
        """Returns number of rows affected by last statement

        Note that this returns the number of changed rows due to the last statement
        executed in this connection*, not cursor.
        """
        return self.conn.changes()
